 function renderBattle(message){const b=activeBattle,p=companion(),s=spec(b.species),a=spec(p.species);document.getElementById('battleTitle').textContent='A wild '+s.name+' appeared!';document.getElementById('enemyName').textContent=s.name;document.getElementById('enemyLevel').textContent='LV '+b.level;document.getElementById('enemySprite').textContent=s.emoji;document.getElementById('enemyHp').style.width=Math.max(0,b.hp/b.max*100)+'%';document.getElementById('allyName').textContent=a.name;document.getElementById('allyLevel').textContent='LV '+p.level;document.getElementById('allySprite').textContent=a.emoji;document.getElementById('allyHp').style.width=Math.max(0,p.hp/a.max*100)+'%';document.getElementById('battleMessage').textContent=message;let acts=[{label:'✦  Quick strike',action:strike},{label:'🍓  Use berry ('+state.berries+')',action:useBerry},{label:'🔴  Trail capsule ('+state.capsules+')',action:capture,capture:true},{label:'↗  Leave',action:flee}];document.getElementById('battleActions').innerHTML='';acts.forEach((v,i)=>{let btn=document.createElement('button');btn.className='action-btn'+(v.capture?' capture':'');btn.textContent=v.label;btn.disabled=battleBusy||(i===2&&state.capsules<1)||(i===1&&(state.berries<1||companion().hp>=spec(companion().species).max));btn.onclick=v.action;document.getElementById('battleActions').append(btn)})}
 function enemyTurn(message){if(!activeBattle)return;battleBusy=true;renderBattle(message);setTimeout(()=>{if(!activeBattle)return;const b=activeBattle,p=companion(),s=spec(b.species),dmg=Math.max(2,Math.floor(s.attack*.55+Math.random()*s.attack*.65-b.turn*.3));p.hp=Math.max(0,p.hp-dmg);b.turn++;if(p.hp<=0){p.hp=Math.max(1,Math.floor(spec(p.species).max*.45));state.berries=Math.max(0,state.berries-1);endBattle(s.name+' settled down. '+spec(p.species).name+' needs a rest.');return}battleBusy=false;updateUI();saveGame();renderBattle(s.name+' gave a playful little bump! Your companion lost '+dmg+' vigor.');},600)}
 function strike(){if(!activeBattle||battleBusy)return;const b=activeBattle,p=companion(),a=spec(p.species),damage=Math.max(4,Math.floor(a.attack*(.75+Math.random()*.55)+p.level));b.hp=Math.max(0,b.hp-damage);if(b.hp<=0){state.shards+=1;battleBusy=true;renderBattle(a.name+' made a new friend! +1 sun-shard');setTimeout(()=>endBattle('You and '+a.name+' found a rhythm. +1 sun-shard.'),800);return}enemyTurn(a.name+' used Leaf Flick!')}
 function useBerry(){if(!activeBattle||battleBusy||state.berries<1)return;state.berries--;const p=companion(),s=spec(p.species);p.hp=Math.min(s.max,p.hp+15);enemyTurn('A sweet berry restored '+p.name+' by 15 vigor.')}
-function capture(){if(!activeBattle||battleBusy||state.capsules<1)return;state.capsules--;const b=activeBattle,s=spec(b.species),chance=.38+(1-b.hp/b.max)*.52;if(Math.random()<chance&&state.party.length<4){state.party.push({species:b.species,level:b.level,hp:s.max+2*b.level,xp:0});if(state.story===2)state.story=3;updateUI();battleBusy=true;renderBattle(s.name+' curled up in your trail capsule!');setTimeout(()=>endBattle(s.name+' joined your companions!'),850);return}enemyTurn('The capsule wobbled… then '+s.name+' popped back out!')}
+function capture(){if(!activeBattle||battleBusy||state.capsules<1)return;if(state.party.length>=4){renderBattle('Your four-companion party is full. Visit Elder Fern to decide who joins your trail.');return}state.capsules--;const b=activeBattle,s=spec(b.species),chance=.38+(1-b.hp/b.max)*.52;if(Math.random()<chance&&state.party.length<4){state.party.push({species:b.species,level:b.level,hp:s.max+2*b.level,xp:0});if(state.story===2)state.story=3;updateUI();battleBusy=true;renderBattle(s.name+' curled up in your trail capsule!');setTimeout(()=>endBattle(s.name+' joined your companions!'),850);return}enemyTurn('The capsule wobbled… then '+s.name+' popped back out!')}
 function flee(){if(!activeBattle||battleBusy)return;if(activeBattle.forced){renderBattle('There’s no rush. Stay a little longer, or make a new friend.');return}if(Math.random()<.8)endBattle('You slipped away safely.');else enemyTurn('The wild one blocks your path!')}
 function endBattle(message){document.getElementById('battleModal').classList.remove('open');activeBattle=null;battleBusy=false;updateUI();saveGame();toast(message)}
 function drawMap(){const c=document.getElementById('minimap'),m=c.getContext('2d'),tw=c.width/MW,th=c.height/MH;m.clearRect(0,0,c.width,c.height);for(let y=0;y<MH;y++)for(let x=0;x<MW;x++){let t=get(x,y);m.fillStyle=t===T.WATER?'#77b6c0':t===T.TREE?'#426952':t===T.TALL?'#8fbd83':t===T.PATH||t===T.BRIDGE?'#d9c18e':t===T.FLOWER?'#96c486':'#70a87a';m.fillRect(x*tw,y*th,tw+.3,th+.3)}m.fillStyle='#daa975';m.fillRect(29*tw,26*th,21*tw,17*th);m.fillStyle='#ba7958';for(const s of structures)m.fillRect(s.x*tw,s.y*th,s.w*tw,s.h*th);m.fillStyle='#fff1a3';m.beginPath();m.arc(player.x*tw+tw/2,player.y*th+th/2,5,0,Math.PI*2);m.fill();m.strokeStyle='#5e5038';m.lineWidth=1.5;m.stroke()}
 function keyDown(e){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d'].includes(k))e.preventDefault();if(k===' '||k==='enter'){if(!keys[k])interact();keys[k]=true;return}keys[k]=true}function keyUp(e){keys[e.key.toLowerCase()]=false}
